/* site-wide scrollbar (owner 2026-09-13: "scroll bar nije crne boje, napravi da bude cool") -- desktop pointers only; phones keep the native overlay bar. Dark track, slim inset thumb, lime on hover; also every inner scroll box (tables, drawers, chat). */
(function(){try{if(document.getElementById("mpsb-css"))return;var st=document.createElement("style");st.id="mpsb-css";st.textContent="@media(min-width:981px) and (pointer:fine){html{scrollbar-width:thin;scrollbar-color:#2a3140 #0a0b0d}*{scrollbar-width:thin;scrollbar-color:#2a3140 transparent}::-webkit-scrollbar{width:10px;height:10px}html::-webkit-scrollbar-track{background:#0a0b0d}::-webkit-scrollbar-track{background:rgba(255,255,255,.03);border-radius:8px}::-webkit-scrollbar-thumb{background:linear-gradient(180deg,#2e3644,#1e242c);background-clip:padding-box;border-radius:8px;border:2px solid transparent}::-webkit-scrollbar-thumb:hover{background:linear-gradient(180deg,#c2f64a,#8fbf2a);background-clip:padding-box}::-webkit-scrollbar-corner{background:#0a0b0d}}";(document.head||document.documentElement).appendChild(st);}catch(e){}})();

/* BREATHING notification marks (owner 2026-09-13: "profil ikona (glow) i chat (plava tačka) da dišu, da trepere"). Driven by the
   Web Animations API, NOT CSS @keyframes: the owner's Windows has animation effects off (prefers-reduced-motion), which
   silences keyframes but not element.animate(). One pulse for the profile dot (.mpa-trig-dot), one for the lit ring on the
   profile trigger (.mpa-unread) and one for the chat FAB dot (.ctfab-dot, created by home.js / mp-trade.js). Marks are
   picked up by a MutationObserver, so no caller needs to know about this; a removed mark takes its animation with it. */
(function () {
  try {
    var live = new WeakMap();
    function pulse(el, kind) {
      if (!el || !el.animate || live.has(el)) return;
      var kf, opt = { duration: 1600, iterations: Infinity, easing: 'ease-in-out' };
      if (kind === 'ring') kf = [{ boxShadow: '0 0 0 1px rgba(194,246,74,.55),0 0 16px -2px rgba(194,246,74,.6)' }, { boxShadow: '0 0 0 2px rgba(194,246,74,.95),0 0 22px 2px rgba(194,246,74,.95)' }, { boxShadow: '0 0 0 1px rgba(194,246,74,.55),0 0 16px -2px rgba(194,246,74,.6)' }];
      else kf = [{ transform: 'scale(1)', opacity: 1 }, { transform: 'scale(1.5)', opacity: .55 }, { transform: 'scale(1)', opacity: 1 }];
      try { live.set(el, el.animate(kf, opt)); } catch (e) {}
    }
    function stop(el) { var a = live.get(el); if (a) { try { a.cancel(); } catch (e) {} live.delete(el); } }
    function sweep() {
      var i, dots = document.querySelectorAll('.mpa-trig-dot, .ctfab-dot');
      for (i = 0; i < dots.length; i++) pulse(dots[i], 'dot');
      var trig = document.querySelectorAll('[data-auth-open]');
      for (i = 0; i < trig.length; i++) { if (trig[i].classList.contains('mpa-unread')) pulse(trig[i], 'ring'); else stop(trig[i]); }
    }
    window.mpBreatheSweep = sweep;
    var mo = new MutationObserver(function (recs) {
      var need = false;
      for (var r = 0; r < recs.length && !need; r++) { var m = recs[r]; if (m.type === 'attributes') need = true; else if (m.addedNodes && m.addedNodes.length) need = true; }
      if (need) sweep();
    });
    var boot = function () { try { mo.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] }); } catch (e) {} sweep(); };
    if (document.body) boot(); else document.addEventListener('DOMContentLoaded', boot);
  } catch (e) {}
})();

/* SUPERNOVA - the apex frame's motion (2026-09-13). CSS @keyframes are invisible on the owner's Windows (animation
   effects off => prefers-reduced-motion: reduce), and this frame IS its motion, so a rAF loop writes the three custom
   properties the rules above read: --nvA (the plasma ring's angle), --nvP (0-1 core pulse) and --nvF (flare drift).
   The loop only exists while a .frame-supernova is in the document, stops with the tab hidden, and is picked up by a
   MutationObserver, so no caller has to know about it. window.mpNovaSweep() re-scans after a manual DOM swap. */
(function () {
  try {
    // Every frame whose motion is JS-driven. @keyframes are invisible with system animation effects off, which is how
    // the owner's machine runs, so anything that IS its motion has to be driven from here.
    var SEL = '.frame-supernova,.frame-owner,.frame-regalia';
    var els = [], raf = 0, t0 = 0;
    function frame(ts) {
      raf = 0;
      if (!els.length) return;
      if (!t0) t0 = ts;
      var t = (ts - t0) / 1000;
      var ang = (t * 15) % 360;                        // one full turn of the ring every 24 s
      var p = 0.5 + 0.5 * Math.sin(t * 2.6);           // core pulse, ~2.4 s in and out
      var f = Math.sin(t * 0.7);                       // slow flare drift across the card
      var a = ang.toFixed(1) + 'deg', ps = p.toFixed(3), fs = f.toFixed(3);
      for (var i = 0; i < els.length; i++) { var e = els[i]; e.style.setProperty('--nvA', a); e.style.setProperty('--nvP', ps); e.style.setProperty('--nvF', fs); }
      if (!document.hidden) raf = requestAnimationFrame(frame);
    }
    function run() { if (!raf && els.length && !document.hidden) raf = requestAnimationFrame(frame); }
    function sweep() {
      try { els = [].slice.call(document.querySelectorAll(SEL)); } catch (e) { els = []; }
      if (els.length) run(); else if (raf) { cancelAnimationFrame(raf); raf = 0; }
    }
    window.mpNovaSweep = sweep;
    document.addEventListener('visibilitychange', function () { if (document.hidden) { if (raf) { cancelAnimationFrame(raf); raf = 0; } } else run(); });
    var mo = new MutationObserver(function (recs) {
      for (var r = 0; r < recs.length; r++) { var m = recs[r]; if (m.type === 'attributes' || (m.addedNodes && m.addedNodes.length) || (m.removedNodes && m.removedNodes.length)) { sweep(); return; } }
    });
    var boot = function () { try { mo.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] }); } catch (e) {} sweep(); };
    if (document.body) boot(); else document.addEventListener('DOMContentLoaded', boot);
  } catch (e) {}
})();

/* ── message actions: the long press, and the sheet it opens (2026-09-14) ────────────────────────────────────────
   Shared because the room chat (WebSocket, home.js + mp-trade.js) and direct messages (REST, this file) both need
   the identical gesture and the identical sheet. Each caller supplies only what differs: which rows are pressable,
   what the reader may do to this one, and what to run when they pick something.

   window.mpLongPress(container, rowSelector, onPick)  - 480 ms hold, or right-click; cancels on a 10 px drag, and
     never fires on a link, a username or a button, because those already do something.
   window.mpMsgSheet({row, reactions, canEdit, canDelete, onReact, onEdit, onDelete, onCopy, text})               */
(function () {
  if (window.mpMsgSheet) return;
  var sheet = null, sheetAt = 0, sheetRow = null, sheetTop = 0;
  function close() { if (sheet && sheet.parentNode) sheet.parentNode.removeChild(sheet); sheet = null; sheetRow = null; }
  window.mpMsgSheetClose = close;
  window.mpMsgSheet = function (o) {
    o = o || {}; if (!o.row) return; close();
    var s = document.createElement('div'); s.className = 'ct-sheet'; s.setAttribute('role', 'menu');
    var h = '', rx = o.reactions || [];
    if (rx.length) { h += '<div class="ct-sh-rx">'; for (var i = 0; i < rx.length; i++) h += '<button type="button" data-sx="' + rx[i] + '">' + rx[i] + '</button>'; h += '</div>'; }
    h += '<div class="ct-sh-a"><button type="button" data-sa="copy">Copy</button>';
    if (o.canEdit) h += '<button type="button" data-sa="edit">Edit</button>';
    if (o.canDelete) h += '<button type="button" data-sa="del" class="dz">Delete</button>';
    h += '</div>';
    s.innerHTML = h; document.body.appendChild(s); sheet = s; sheetAt = Date.now();
    sheetRow = o.row; sheetTop = o.row.getBoundingClientRect().top;
    try { var sel = window.getSelection && window.getSelection(); if (sel && sel.removeAllRanges) sel.removeAllRanges(); } catch (e) {}
    var r = o.row.getBoundingClientRect(), sw = s.offsetWidth, sh = s.offsetHeight;
    var left = Math.max(8, Math.min(window.innerWidth - sw - 8, r.left));
    var top = r.top - sh - 8; if (top < 8) top = Math.min(window.innerHeight - sh - 8, r.bottom + 8);
    s.style.left = left + 'px'; s.style.top = top + 'px'; s.classList.add('on');
    s.addEventListener('click', function (ev) {
      var b = ev.target.closest && ev.target.closest('[data-sx],[data-sa]'); if (!b) return;
      ev.preventDefault(); ev.stopPropagation();
      var e2 = b.getAttribute('data-sx');
      if (e2) { close(); if (o.onReact) o.onReact(e2); return; }
      var a = b.getAttribute('data-sa'); close();
      if (a === 'copy') { var t = o.text != null ? o.text : (o.row.innerText || ''); try { if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(t); } catch (e) {} if (o.onCopy) o.onCopy(t); return; }
      if (a === 'edit' && o.onEdit) o.onEdit();
      if (a === 'del' && o.onDelete) o.onDelete();
    });
  };
  /* touchend fires a click a moment later; without the 450 ms grace the sheet shut the instant the finger lifted. */
  /* Lifting the finger produces a click, and that click would close the sheet the press had just opened. A grace
     measured from the OPEN is not enough - a deliberate hold easily outlasts it - so the press marks its own release
     click and this swallows exactly that one. */
  document.addEventListener('click', function (e) {
    if (!sheet) return;
    if (window.__mpLpRelease && Date.now() - window.__mpLpRelease < 900) { window.__mpLpRelease = 0; return; }
    if (Date.now() - sheetAt < 250) return;
    if (!sheet.contains(e.target)) close();
  }, true);
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') close(); });
  window.addEventListener('resize', close);
  /* Closing on ANY scroll killed the sheet the moment the finger lifted: the release settles the message list by a
     pixel or two and that counts as a scroll. Follow the row instead, and give up only once it has moved far enough
     that the sheet is no longer pointing at it. */
  window.addEventListener('scroll', function () {
    if (!sheet || !sheetRow) return;
    var r = sheetRow.getBoundingClientRect();
    if (r.bottom < 0 || r.top > window.innerHeight || Math.abs(r.top - sheetTop) > 120) { close(); return; }
    var sh = sheet.offsetHeight, top = r.top - sh - 8;
    if (top < 8) top = Math.min(window.innerHeight - sh - 8, r.bottom + 8);
    sheet.style.top = top + 'px';
  }, true);

  window.mpLongPress = function (box, sel, onPick) {
    if (!box || box._mpLp) return; box._mpLp = 1;
    var t = null, fired = false, xy = null;
    /* A press must not steal what the row already does - a username opens a profile, a link is a link. A SHARED
       TRADE is different: it is rendered as a link (.ct-trade) or a card (.ct-sig) but it IS the message, so a hold
       has to reach it (owner 2026-09-14: "shared trades ... ako se prst zadrzi na njima, treba da moze da se ostavi
       reakcija"). A tap still opens the ticket - the press swallows only its own release click. */
    var skip = function (n) {
      if (!n.closest) return false;
      if (n.closest('.ct-user') || n.closest('.ct-rxb') || n.closest('.mpa-rxb')) return true;
      if (n.closest('.ct-sig') || n.closest('.ct-trade')) return false;
      return !!(n.closest('a') || n.closest('button'));
    };
    var rowOf = function (n) { return n.closest && n.closest(sel); };
    box.addEventListener('touchstart', function (e) {
      var row = rowOf(e.target); if (!row || skip(e.target)) return;
      fired = false; xy = [e.touches[0].clientX, e.touches[0].clientY];
      clearTimeout(t); t = setTimeout(function () { fired = true; if (window.mpHaptic) window.mpHaptic('tick'); onPick(row); }, 480);
    }, { passive: true });
    box.addEventListener('touchmove', function (e) { if (!xy || !e.touches[0]) return; if (Math.abs(e.touches[0].clientX - xy[0]) > 10 || Math.abs(e.touches[0].clientY - xy[1]) > 10) clearTimeout(t); }, { passive: true });
    box.addEventListener('touchend', function () { clearTimeout(t); if (fired) window.__mpLpRelease = Date.now(); }, { passive: true });
    box.addEventListener('touchcancel', function () { clearTimeout(t); }, { passive: true });
    box.addEventListener('contextmenu', function (e) { var row = rowOf(e.target); if (!row || skip(e.target)) return; e.preventDefault(); onPick(row); });
    box.addEventListener('click', function (e) { if (fired) { fired = false; e.preventDefault(); e.stopPropagation(); } }, true);
  };
})();

/* ── haptics ─────────────────────────────────────────────────────────────────────────────────────────────────────
   window.mpHaptic('step'|'tick'|'ok'|'warn') - a confirmation you can feel, for the few moments that earn one: a
   position opening or closing, an order landing, each step of the leverage ladder. window.mpBuzz(pattern) is the raw
   form the older call sites use. It lives HERE, in the every-page bundle, because it used to live in home.js and every
   caller outside the six app-shell routes was silently dead (same exception as mpToast / mpOrders / mpEx).

   Deliberately NOT gated on prefers-reduced-motion - the owner's machine has animation effects off and would never
   feel it, and a buzz is not motion on a screen. Off entirely with localStorage mp_haptics=0.
   navigator.vibrate does not exist on desktop or on iOS: there this is a property lookup and a return, no listeners,
   nothing loaded. The userActivation gate is what keeps Chrome from logging a blocked-vibrate warning. */
(function () {
  var P = { step: 7, tick: 12, ok: [15, 40, 15], warn: [22, 55, 22] };
  var off = null, last = 0;
  function fire(pattern, minGap) {
    try {
      if (!navigator.vibrate) return false;
      if (off === null) { try { off = localStorage.getItem('mp_haptics') === '0'; } catch (e) { off = false; } }
      if (off) return false;
      var ua = navigator.userActivation;
      if (ua && !ua.hasBeenActive) return false;   // Chrome refuses (and warns) before the first interaction
      var now = Date.now();
      if (now - last < (minGap || 0)) return false;
      last = now;
      navigator.vibrate(pattern);
      return true;
    } catch (e) { return false; }
  }
  /* a dragged slider must tick per STEP of the ladder, never per frame of the drag */
  window.mpHaptic = function (kind) { return fire(P[kind] || P.tick, kind === 'step' ? 45 : 0); };
  if (!window.mpBuzz) window.mpBuzz = function (p) { return fire(p, 0); };
})();
